import{d as s,C as a,o as h,c as g,E as t,a3 as n}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"咸卦","description":"第三十一卦·泽山咸——山上有泽，君子以虚受人。","frontmatter":{"title":"咸卦","description":"第三十一卦·泽山咸——山上有泽，君子以虚受人。","category":"hexagram","aliases":["咸","泽山咸"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-31.md","filePath":"yijing/hexagrams/hexagram-31.md","lastUpdated":1787730063000}'),m={name:"yijing/hexagrams/hexagram-31.md"},q=s({...m,setup(p){const r=[{id:"xianqimu",term:"咸其拇",pinyin:"xián qí mǔ",meaning:"感应到脚趾。拇，足趾。最初的触动，尚未被意念加工。"},{id:"xianqifei",term:"咸其腓",pinyin:"xián qí féi",meaning:"感应到小腿肚。腓，小腿肚。被感带动，切忌抢先妄动。"},{id:"xianqigu",term:"咸其股",pinyin:"xián qí gǔ",meaning:"感应到大腿。股，大腿。主控感出现，执著于「我要跟随感应」。"},{id:"zhiqisui",term:"执其随",pinyin:"zhí qí suí",meaning:"执著于跟随这件事。从自然感应，滑向「我要感应」。"},{id:"chongchong",term:"憧憧往来",pinyin:"chōng chōng wǎng lái",meaning:"心念来去不定。念头不断出入，连「我要不想了」也成为一个念。"},{id:"pengcong",term:"朋从尔思",pinyin:"péng cóng ěr sī",meaning:"内心长久系于什么，相关的人、事、念头便会随之聚集、响应。"},{id:"xianqimei",term:"咸其脢",pinyin:"xián qí méi",meaning:"感应到脊背。脢，背脊肉。内守、有根、有感而不被牵走。"},{id:"xianqifu",term:"咸其辅颊舌",pinyin:"xián qí fǔ jiá shé",meaning:"感应到辅、颊、舌。辅颊为面部外显，舌为内在出口——感应化为表情、语言、书写。"},{id:"zhizaiwai",term:"志在外",pinyin:"zhì zài wài",meaning:"志向在外。最初的触动，尚未形成可判断的方向。"},{id:"shunbuhai",term:"顺不害",pinyin:"shùn bù hài",meaning:"顺而不害。安守其位，让行动自然成熟，而不是由焦虑催促。"},{id:"zhizaisuiren",term:"志在随人",pinyin:"zhì zài suí rén",meaning:"志向在随人。执著于跟随，所执已经落了下乘。"},{id:"weiganhai",term:"未感害",pinyin:"wèi gǎn hài",meaning:"没有感应之害。贞吉悔亡，因为守正不被感应所害。"},{id:"weiguangda",term:"未光大",pinyin:"wèi guāng dà",meaning:"尚未光大。憧憧往来，心念纷纭则尚未光大。"},{id:"zhimo",term:"志末",pinyin:"zhì mò",meaning:"志向在末。守在脊背，不是追逐感受的末端，而是回到支撑自己的根。"},{id:"tengkoushuo",term:"滕口说",pinyin:"téng kǒu shuō",meaning:"张口空说。若只停在口舌，便是空说；表达之后，还要能回到本质。"}],e=[{position:"初六",type:"yin",text:"咸其拇。",xiang:"咸其拇，志在外也。",textModern:"感应从脚趾开始——脚趾与地相接，人不是先用概念接触世界，而是先以身体接触世界。感应本来一直都在，修习不是制造感应，是重新注意到它。",xiangModern:"感应到脚趾，志向在外——最初的触动，尚未形成可判断的方向。"},{position:"六二",type:"yin",text:"咸其腓，凶，居吉。",xiang:"虽凶居吉，顺不害也。",textModern:"脚趾一动，小腿会自然被带动；但若强迫小腿抢先发力，就打乱了自然次序。动则凶，居则吉——先居住在感受里，不急着把感受变成动作。",xiangModern:"虽凶居吉，顺而不害——安守其位，让行动自然成熟，而不是由焦虑催促。"},{position:"九三",type:"yang",text:"咸其股，执其随，往吝。",xiang:"咸其股，亦不处也。志在随人，所执下也。",textModern:"感应到大腿，「小我」开始出现——「我在掌控方向」。「执其随」不是单纯跟随，是执著于跟随这件事：从自然感应，滑向「我要感应」。",xiangModern:"咸其股，亦不处也，志在随人——执著于跟随，所执已经落了下乘。"},{position:"九四",type:"yang",text:"贞吉，悔亡。憧憧往来，朋从尔思。",xiang:"贞吉悔亡，未感害也。憧憧往来，未光大也。",textModern:"心是感应的中心，也是念头的市场。「憧憧往来」是念头不断出入；「朋从尔思」是你长期安住什么念，相关人事便向那个方向聚集。但关键不在「乱」，在开头四字「贞吉悔亡」——在乱中守正，乱才会成为通向安定的过程。",xiangModern:"贞吉悔亡，未感害也；憧憧往来，未光大也——守正则不被感应所害，心念往来则尚未光大。"},{position:"九五",type:"yang",text:"咸其脢，无悔。",xiang:"咸其脢，志末也。",textModern:"感应到脊背——脊背不负责展示、不负责言说，却默默支撑整个身体。九五的重点不是更多感受，是内守：有感，但不被感带走。",xiangModern:"咸其脢，志末也——守在脊背，不是追逐感受的末端，而是回到支撑自己的根。"},{position:"上六",type:"yin",text:"咸其辅颊舌。",xiang:"咸其辅颊舌，滕口说也。",textModern:"感应走完全身后，终于找到出口，化为表情、语言、书写与行动。关键不是说多说少，是如实、合时、不夸张、不借表达操控。感受了，如实表达；不压抑、不表演、不夸大、也不伤人。",xiangModern:"咸其辅颊舌，滕口说也——若只停在口舌，便是张口空说；表达之后，还要能回到本质。"}];return(u,i)=>{const o=a("DaoHexagramViewer"),l=a("DaoHexagramYaoCards"),d=a("DaoKeywordCards");return h(),g("div",null,[t(o,{name:"咸",fullName:"泽山咸",upper:"☱",lower:"☶",guaCi:"咸，亨，利贞。取女吉。",pinyin:["xián"],element:"金",direction:"西",insight:"泽在山上，虚而能受；感是入口，贞是边界。",guaSlug:"31zeshanxian",lines:e}),i[0]||(i[0]=n("",10)),t(l,{element:"金",guaSlug:"31zeshanxian",glossary:r,items:e}),i[1]||(i[1]=n("",21)),t(d,{title:"字词释义",items:[{term:"咸",pinyin:["xián"],meaning:"感。无心之感，不以私心强作感应。"},{term:"拇",pinyin:["mǔ"],meaning:"脚趾。感应最初的触动。"},{term:"腓",pinyin:["féi"],meaning:"小腿肚。被感带动，切忌抢先妄动。"},{term:"股",pinyin:["gǔ"],meaning:"大腿。主控感出现，执著于跟随。"},{term:"憧憧",pinyin:["chōng","chōng"],meaning:"往来不定、心念纷纭。"},{term:"脢",pinyin:["méi"],meaning:"背脊肉。内守、有根、有感而不被牵走。"},{term:"辅颊舌",pinyin:["fǔ","jiá","shé"],meaning:"面颊与口舌，表达系统。"},{term:"虚受人",pinyin:["xū","shòu","rén"],meaning:"心中留有空间，容纳他人的处境与存在。"},{term:"朋从尔思",pinyin:["péng","cóng","ěr","sī"],meaning:"心念所系，同类相从。"},{term:"取女吉",pinyin:["qǔ","nǚ","jí"],meaning:"男下女，刚者下就于柔者，故能感通。"}]}),i[2]||(i[2]=n("",22))])}}});export{x as __pageData,q as default};
